// Package web exposes the frontend build that is compiled into the Go binary.
package web

import (
	"embed"
	"io/fs"
)

// The frontend build is generated by "pnpm build:js". Run that before
// "go build"; the embed directive makes the build a compile-time dependency.
//
//go:embed all:build
var build embed.FS

// Build returns the embedded frontend rooted at web/build.
func Build() fs.FS {
	root, err := fs.Sub(build, "build")
	if err != nil {
		// "build" is part of the embed directive, so this cannot fail unless
		// the compiled-in filesystem itself is malformed.
		panic("embedded web build: " + err.Error())
	}
	return root
}
